import { Component, input } from '@angular/core';

@Component({
  selector: 'app-badge',
  template: `<span class="badge">{{ label() }}</span>`,
  styles: `.badge { background: #e5e7eb; }`,
})
export class Badge {
  readonly label = input('');
}

@Component({
  selector: 'app-product-card',
  imports: [Badge],
  template: `<app-badge label="Sale" />`,
  // Global: recolors every .badge in the app
  styles: `::ng-deep .badge { background: crimson; }`,
})
export class ProductCard {}

